    Staged.objects.filter(paper__is_student_private=True).exclude(correct_option="").update(answer_status="student_confirmed")
    Staged.objects.filter(paper__is_student_private=False).exclude(correct_option="").update(answer_status="manually_verified")
    unambiguous = (Question.objects.annotate(correct_count=Count("options", filter=Q(options__is_correct=True)))
                   .filter(correct_count=1))
    # The old private flag applies only to student-created practice keys.
    Question.objects.filter(pk__in=unambiguous.filter(is_private_practice=True, key_verified=True).values_list("pk", flat=True)).update(answer_status="student_confirmed")
